//go:build linux

// Command nettrace is a throwaway spike (DEVDESK-385, S-01): can an
// unprivileged process trace a path with UDP probes of growing TTL and read the
// ICMP Time Exceeded replies through IP_RECVERR and MSG_ERRQUEUE? It is
// standalone (standard library only), IPv4 only, and prints a report meant to
// be pasted as is. It is never merged.
package main

import (
	"context"
	"encoding/binary"
	"errors"
	"flag"
	"fmt"
	"net"
	"net/netip"
	"os"
	"runtime"
	"sort"
	"strings"
	"sync"
	"syscall"
	"time"
)

// commit is set at build time with -ldflags "-X main.commit=<sha>".
var commit = "unknown"

const (
	// ipRecvErr is IP_RECVERR; package syscall does not export it.
	ipRecvErr = 11
	// basePort is the first destination port; a probe uses basePort+ttl.
	basePort = 33434
	// hardMaxTTL is the decided maximum TTL of the spike.
	hardMaxTTL = 30
	// hardDeadline is the decided maximum duration of one trace.
	hardDeadline = 30 * time.Second

	icmpDestUnreach  = 3
	icmpTimeExceeded = 11
	icmpPortUnreach  = 3 // code, with icmpDestUnreach
	soEeOriginICMP   = 2
)

// kind is what the error queue told about one probe.
type kind int

const (
	kindSilent     kind = iota // no error before the probe timeout
	kindTimeExceed             // ICMP Time Exceeded from a router
	kindReached                // ICMP Port Unreachable from the target
	kindUnreach                // another ICMP Destination Unreachable
	kindCancelled              // the trace ended before the probe resolved
	kindSockErr                // local failure (setsockopt, send, recv)
)

func (k kind) String() string {
	switch k {
	case kindSilent:
		return "silent"
	case kindTimeExceed:
		return "time-exceeded"
	case kindReached:
		return "target-reached"
	case kindUnreach:
		return "unreachable"
	case kindCancelled:
		return "unresolved"
	default:
		return "socket-error"
	}
}

// outcome is the explicit result of a trace.
type outcome int

const (
	outReached    outcome = iota // target reached
	outTTLMax                    // target not reached, maximum TTL
	outDelay                     // target not reached, delay elapsed
	outCancelled                 // cancelled by the caller
	outInconclusv                // not used for decisions
)

func (o outcome) String() string {
	switch o {
	case outReached:
		return "target reached"
	case outTTLMax:
		return "target not reached, maximum TTL"
	case outDelay:
		return "target not reached, delay elapsed"
	case outCancelled:
		return "cancelled"
	default:
		return "inconclusive"
	}
}

type probe struct {
	TTL     int
	Kind    kind
	Addr    netip.Addr
	Latency time.Duration
	Code    int    // ICMP type/code detail for kindUnreach
	Detail  string // raw error text, never shown as a summary
	SockOpt string // setsockopt error text, empty when fine
}

type result struct {
	Target   string
	MaxTTL   int
	Timeout  time.Duration
	Duration time.Duration
	Outcome  outcome
	Probes   []probe // index ttl-1
	Hops     []probe // probes up to the target (or all)
	Pending  int     // unresolved probes when the trace ended
}

func main() {
	target := flag.String("target", "1.1.1.1", "public target (IPv4 address or name)")
	unreach := flag.String("unreachable", "192.0.2.1", "target that never answers (documentation block)")
	maxTTL := flag.Int("max-ttl", hardMaxTTL, "maximum TTL")
	timeout := flag.Duration("probe-timeout", 3*time.Second, "per-probe timeout")
	deadline := flag.Duration("deadline", hardDeadline, "whole-trace deadline")
	cycles := flag.Int("cycles", 100, "cancellation cycles for L7")
	extra := flag.String("extra-targets", "", "comma-separated extra targets traced once, to look for a silent hop (L4)")
	flag.Parse()

	if *maxTTL < 1 || *maxTTL > hardMaxTTL {
		fmt.Fprintf(os.Stderr, "max-ttl must be in 1..%d\n", hardMaxTTL)
		os.Exit(2)
	}
	if *deadline > hardDeadline {
		fmt.Fprintf(os.Stderr, "deadline is capped at %s\n", hardDeadline)
		os.Exit(2)
	}
	rep := &report{}
	rep.header(*target, *unreach, *maxTTL, *timeout, *deadline, *cycles)

	// Main trace: L1, L2, L3, L4, L6.
	main1 := trace(context.Background(), *target, *maxTTL, *timeout, *deadline)
	rep.printTrace("Main trace", main1)

	// L6 measurement: real path if it has at least 8 hops, else TTL bounded to 8.
	l6 := measureL6(main1, *target, *timeout, *deadline)
	rep.printL6(l6)

	// L5 measurements.
	l5 := measureL5(*target, *unreach, *timeout)
	rep.printL5(l5)

	// L4 candidates.
	var extras []result
	for _, t := range strings.Split(*extra, ",") {
		if t = strings.TrimSpace(t); t != "" {
			r := trace(context.Background(), t, *maxTTL, *timeout, *deadline)
			rep.printTrace("Extra trace (L4 candidate)", r)
			extras = append(extras, r)
		}
	}

	// L7.
	l7 := measureL7(*unreach, *cycles, *timeout)
	rep.printL7(l7)

	rep.verdicts(main1, l6, l5, extras, l7)
	fmt.Print(rep.String())
}

// ---------------------------------------------------------------- engine

// trace sends one UDP probe per TTL in parallel, each from its own socket, and
// reads the Time Exceeded replies from the socket error queue. It returns once
// every TTL up to the target (or up to maxTTL) is resolved, the deadline has
// passed or ctx is cancelled. Every socket is closed before it returns.
func trace(ctx context.Context, target string, maxTTL int, timeout, deadline time.Duration) result {
	start := time.Now()
	res := result{Target: target, MaxTTL: maxTTL, Timeout: timeout, Probes: make([]probe, maxTTL)}
	ctx, cancelDeadline := context.WithTimeout(ctx, deadline)
	defer cancelDeadline()
	pctx, cancelProbes := context.WithCancel(ctx)
	defer cancelProbes()

	ip, err := resolveV4(target)
	if err != nil {
		res.Probes = nil
		res.Outcome = outCancelled
		res.Hops = []probe{{Kind: kindSockErr, Detail: err.Error()}}
		return res
	}

	out := make(chan probe, maxTTL)
	var wg sync.WaitGroup
	for ttl := 1; ttl <= maxTTL; ttl++ {
		wg.Add(1)
		go func(ttl int) {
			defer wg.Done()
			out <- sendProbe(pctx, ip, ttl, timeout)
		}(ttl)
	}

	resolved := make([]bool, maxTTL+1)
	limit := maxTTL // highest TTL that must be resolved
	done := false
	for got := 0; got < maxTTL && !done; got++ {
		select {
		case p := <-out:
			res.Probes[p.TTL-1] = p
			resolved[p.TTL] = true
			if p.Kind == kindReached && p.TTL < limit {
				limit = p.TTL
			}
			done = allResolved(resolved, limit)
		case <-ctx.Done():
			done = true
		}
	}
	cancelProbes()
	wg.Wait()
	close(out)
	for p := range out { // probes that finished while shutting down
		if !resolved[p.TTL] && p.Kind != kindCancelled {
			res.Probes[p.TTL-1] = p
			resolved[p.TTL] = true
		}
	}
	res.Duration = time.Since(start)

	reached := 0
	for i := range res.Probes {
		if res.Probes[i].TTL == 0 {
			res.Probes[i] = probe{TTL: i + 1, Kind: kindCancelled}
		}
		if res.Probes[i].Kind == kindReached && (reached == 0 || i+1 < reached) {
			reached = i + 1
		}
	}
	switch {
	case reached > 0:
		res.Outcome = outReached
		res.Hops = res.Probes[:reached]
	case errors.Is(ctx.Err(), context.DeadlineExceeded):
		res.Outcome = outDelay
		res.Hops = res.Probes
	case ctx.Err() != nil:
		res.Outcome = outCancelled
		res.Hops = res.Probes
	default:
		res.Outcome = outTTLMax
		res.Hops = res.Probes
	}
	for _, p := range res.Probes {
		if p.Kind == kindCancelled {
			res.Pending++
		}
	}
	return res
}

func allResolved(resolved []bool, limit int) bool {
	for t := 1; t <= limit; t++ {
		if !resolved[t] {
			return false
		}
	}
	return true
}

func resolveV4(target string) (netip.Addr, error) {
	if a, err := netip.ParseAddr(target); err == nil {
		if !a.Is4() {
			return netip.Addr{}, fmt.Errorf("%s is not an IPv4 address", target)
		}
		return a, nil
	}
	ips, err := net.LookupIP(target)
	if err != nil {
		return netip.Addr{}, err
	}
	for _, ip := range ips {
		if v4 := ip.To4(); v4 != nil {
			a, _ := netip.AddrFromSlice(v4)
			return a, nil
		}
	}
	return netip.Addr{}, fmt.Errorf("no IPv4 address for %s", target)
}

// sendProbe owns one socket for one TTL: it sends a datagram, waits on the
// netpoller for the error queue to become readable, and classifies the error.
// The socket is closed before it returns, whatever the outcome.
func sendProbe(ctx context.Context, dst netip.Addr, ttl int, timeout time.Duration) probe {
