	var optErr error
	d := net.Dialer{Control: func(_, _ string, c syscall.RawConn) error {
		return c.Control(func(fd uintptr) {
			if err := syscall.SetsockoptInt(int(fd), syscall.SOL_IP, syscall.IP_TTL, ttl); err != nil {
				optErr = fmt.Errorf("IP_TTL: %w", err)
				return
			}
			if err := syscall.SetsockoptInt(int(fd), syscall.SOL_IP, ipRecvErr, 1); err != nil {
