	if optErr != nil {
		p.SockOpt = optErr.Error()
	}
	if err != nil {
		p.Detail = "dial: " + err.Error()
		if ctx.Err() != nil {
			p.Kind = kindCancelled
		}
		return p
	}
	defer conn.Close()
	uc := conn.(*net.UDPConn)
	stop := context.AfterFunc(ctx, func() { _ = uc.SetReadDeadline(time.Unix(1, 0)) })
	defer stop()

	sent := time.Now()
	if _, err := uc.Write([]byte("devdesk-nettrace-spike")); err != nil {
		p.Detail = "write: " + err.Error()
		return p
	}
	_ = uc.SetReadDeadline(sent.Add(timeout))
	rc, err := uc.SyscallConn()
	if err != nil {
